long long compute_swaps(char *src, char *tgt, int n) {
    int *src0 = malloc(n * sizeof(int));
    int *tgt0 = malloc(n * sizeof(int));
    int cs = 0, ct = 0;
    for (int i = 0; i < n; i++) {
        if (src[i] == '0') src0[cs++] = i;
        if (tgt[i] == '0') tgt0[ct++] = i;
    }
    if (cs != ct) { free(src0); free(tgt0); return -1; }
    long long res = 0;
    for (int i = 0; i < cs; i++) res += abs(src0[i] - tgt0[i]);
    free(src0); free(tgt0);
    return res;
