typedef long long ll;

static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    char *s = (char *)malloc((n + 5) * sizeof(char));
    if (!s) return 0;
    scanf("%s", s);

    int *a = (int *)malloc(m * sizeof(int));
    if (!a) return 0;

    ll sum = 0;
    for (int i = 0; i < m; ++i) {
        scanf("%d", &a[i]);
        sum += a[i];
    }

    if (sum != n) {
        printf("-1\n");
        free(s);
        free(a);
        return 0;
    }

    int cnt0 = 0, cnt1 = 0;
    for (int i = 0; i < n; ++i) {
        if (s[i] == '0') cnt0++;
        else cnt1++;
    }

    ll INF = (1LL << 62);
    ll answer = INF;

    for (int start = 0; start <= 1; ++start) {
        int need0 = 0, need1 = 0;
        for (int i = 0; i < m; ++i) {
            int bit = start ^ (i & 1);
            if (bit == 0) need0 += a[i];
            else need1 += a[i];
        }
        if (need0 != cnt0 || need1 != cnt1) continue;

        int *targetPos = (int *)malloc((cnt1 > 0 ? cnt1 : 1) * sizeof(int));
        if (!targetPos) {
            free(s);
            free(a);
            return 0;
        }

        int idx1 = 0;
        int pos = 0;
        for (int i = 0; i < m; ++i) {
            int bit = start ^ (i & 1);
            if (bit == 1) {
                for (int k = 0; k < a[i]; ++k) {
                    targetPos[idx1++] = pos + k;
                }
            }
            pos += a[i];
        }

        ll cost = 0;
        int cur1 = 0;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '1') {
                cost += llabs((ll)i - (ll)targetPos[cur1]);
                cur1++;
            }
        }

        answer = minll(answer, cost);
        free(targetPos);
    }

    if (answer == INF) printf("-1\n");
    else printf("%lld\n", answer);

    free(s);
    free(a);
    return 0;
}

