using ll = long long;

static const ll INF = (1LL << 62);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    if (!(cin >> s)) return 0;

    int m;
    cin >> m;
    vector<int> a(m);
    for (int i = 0; i < m; ++i) cin >> a[i];

    int n = (int)s.size();
    int ones = 0;
    for (char c : s) ones += (c == '1');
    int zeros = n - ones;

    ll answer = INF;

    for (int start = 0; start < 2; ++start) {
        // start = 0 means first run is zeros, start = 1 means first run is ones
        int needOnes = 0, needZeros = 0;
        for (int i = 0; i < m; ++i) {
            if (((start + i) & 1) == 1) needOnes += a[i];
            else needZeros += a[i];
        }
        if (needOnes != ones || needZeros != zeros) continue;

        string t;
        t.reserve(n);
        for (int i = 0; i < m; ++i) {
            char ch = (((start + i) & 1) ? '1' : '0');
            t.append(a[i], ch);
        }

        vector<int> posS, posT;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '1') posS.push_back(i);
            if (t[i] == '1') posT.push_back(i);
        }

        ll cost = 0;
        for (int i = 0; i < (int)posS.size(); ++i) {
            cost += llabs((ll)posS[i] - posT[i]);
        }
        answer = min(answer, cost);
    }

    if (answer == INF) cout << -1 << '\n';
    else cout << answer << '\n';

    return 0;
}

