public class MinAdjacentSwapsRunLength {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        String[] parts = br.readLine().trim().split("\\s+");
        int[] runs = new int[parts.length];
        int totalLen = 0;
        for (int i = 0; i < parts.length; i++) {
            runs[i] = Integer.parseInt(parts[i]);
            totalLen += runs[i];
        }

        // Build target string
        StringBuilder targetBuilder = new StringBuilder();
        char bit = '0';
        for (int r : runs) {
            for (int j = 0; j < r; j++) {
                targetBuilder.append(bit);
            }
            bit = (bit == '0') ? '1' : '0';
        }
        String t = targetBuilder.toString();

        // Collect positions of '1' in original and target
        List<Integer> posS = new ArrayList<>();
        List<Integer> posT = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '1') posS.add(i);
            if (t.charAt(i) == '1') posT.add(i);
        }

        // If number of 1s differ, impossible but not happening in valid input
        long swaps = 0;
        for (int i = 0; i < posS.size(); i++) {
            swaps += Math.abs(posS.get(i) - posT.get(i));
        }
        System.out.println(swaps);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long INF = (long) 4e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String s = fs.next();
        if (s == null) return;
        int m = fs.nextInt();
        int[] a = new int[m];
        long sum = 0;
        for (int i = 0; i < m; i++) {
            a[i] = fs.nextInt();
            sum += a[i];
        }

        int n = s.length();
        if (sum != n) {
            System.out.println(-1);
            return;
        }

        ArrayList<Integer> pos0 = new ArrayList<>();
        ArrayList<Integer> pos1 = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') pos0.add(i);
            else pos1.add(i);
        }

        long ans = INF;

        // Try start bit = 0
        if (isFeasible(a, 0, pos0.size(), pos1.size())) {
            ans = Math.min(ans, costForStart(a, 0, pos0, pos1));
        }

        // Try start bit = 1
        if (isFeasible(a, 1, pos0.size(), pos1.size())) {
            ans = Math.min(ans, costForStart(a, 1, pos0, pos1));
        }

        System.out.println(ans >= INF / 2 ? -1 : ans);
    }

    static boolean isFeasible(int[] a, int startBit, int cnt0, int cnt1) {
        long need0 = 0, need1 = 0;
        for (int i = 0; i < a.length; i++) {
            int bit = startBit ^ (i & 1);
            if (bit == 0) need0 += a[i];
            else need1 += a[i];
        }
        return need0 == cnt0 && need1 == cnt1;
    }

    static long costForStart(int[] a, int startBit, ArrayList<Integer> pos0, ArrayList<Integer> pos1) {
        long cost = 0;
        int idx0 = 0, idx1 = 0;
        int curPos = 0;

        for (int i = 0; i < a.length; i++) {
            int bit = startBit ^ (i & 1);
            int len = a[i];
            if (bit == 0) {
                for (int k = 0; k < len; k++) {
                    cost += Math.abs((long) pos0.get(idx0++) - (curPos++));
                }
            } else {
                for (int k = 0; k < len; k++) {
                    cost += Math.abs((long) pos1.get(idx1++) - (curPos++));
                }
            }
        }
        return cost;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            String s = next();
            return s == null ? Integer.MIN_VALUE : Integer.parseInt(s);
        }
    }
}
